-- Phase 3a, migration D: the revision model (design 4.2, ADR 0007). PlanRevision gains `auto`,
-- `decision`, `diff`, `undo`, `undoneAt`, `undoneById`, `undoOf`, `seenAt` and `disruptionId`.
-- The (planId, reason) index is not added here: migration B already created it.
--
-- Generated by `prisma migrate diff`, then edited by hand in the INSERT of the redefine only:
--   * "auto" is backfilled to true for the revisions the scheduler wrote: reason 'weekly' or 'break'.
--   * "seenAt" is backfilled to "createdAt" for every row, so no old revision reads as new.
--   * "diff", "undo" and the other new columns stay null: older revisions have no diff and nothing
--     to undo.
-- Every other column is copied as it is. Nothing references PlanRevision, so no cascade fires while
-- the table is dropped, and the foreign keys are off for the redefine (the PRAGMAs below).

-- RedefineTables
PRAGMA defer_foreign_keys=ON;
PRAGMA foreign_keys=OFF;
CREATE TABLE "new_PlanRevision" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "planId" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "reason" TEXT NOT NULL,
    "summary" TEXT NOT NULL,
    "changes" TEXT NOT NULL DEFAULT '[]',
    "auto" BOOLEAN NOT NULL DEFAULT false,
    "decision" TEXT,
    "diff" TEXT,
    "undo" TEXT,
    "undoneAt" DATETIME,
    "undoneById" TEXT,
    "undoOf" TEXT,
    "seenAt" DATETIME,
    "disruptionId" TEXT,
    CONSTRAINT "PlanRevision_planId_fkey" FOREIGN KEY ("planId") REFERENCES "Plan" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
INSERT INTO "new_PlanRevision" ("auto", "changes", "createdAt", "id", "planId", "reason", "seenAt", "summary") SELECT CASE WHEN "reason" IN ('weekly', 'break') THEN true ELSE false END, "changes", "createdAt", "id", "planId", "reason", "createdAt", "summary" FROM "PlanRevision";
DROP TABLE "PlanRevision";
ALTER TABLE "new_PlanRevision" RENAME TO "PlanRevision";
CREATE INDEX "PlanRevision_planId_createdAt_idx" ON "PlanRevision"("planId", "createdAt");
CREATE INDEX "PlanRevision_planId_reason_idx" ON "PlanRevision"("planId", "reason");
PRAGMA foreign_keys=ON;
PRAGMA defer_foreign_keys=OFF;
